CREATE SCHEMA dw;
GO

CREATE TABLE dw.DIM_DEPARTMENT (
    department_id   INT          NOT NULL,
    department_name VARCHAR(50)  NOT NULL
)
WITH (DISTRIBUTION = REPLICATE, CLUSTERED INDEX (department_id));
ALTER TABLE dw.DIM_DEPARTMENT ADD CONSTRAINT PK_DIM_DEPARTMENT
    PRIMARY KEY NONCLUSTERED (department_id) NOT ENFORCED;

CREATE TABLE dw.DIM_EMPLOYEE (
    employee_id     VARCHAR(10)  NOT NULL,
    employee_name   VARCHAR(50)  NOT NULL,
    department_id   INT          NOT NULL
)
WITH (DISTRIBUTION = REPLICATE, CLUSTERED INDEX (employee_id));
ALTER TABLE dw.DIM_EMPLOYEE ADD CONSTRAINT PK_DIM_EMPLOYEE
    PRIMARY KEY NONCLUSTERED (employee_id) NOT ENFORCED;

CREATE TABLE dw.DIM_DATE (
    [date]       DATE        NOT NULL,
    day_of_week  VARCHAR(10) NOT NULL,
    is_weekend   TINYINT     NOT NULL
)
WITH (DISTRIBUTION = REPLICATE, CLUSTERED INDEX ([date]));
ALTER TABLE dw.DIM_DATE ADD CONSTRAINT PK_DIM_DATE
    PRIMARY KEY NONCLUSTERED ([date]) NOT ENFORCED;

CREATE TABLE dw.FACT_DAILY_ACTIVITY (
    employee_id            VARCHAR(10)  NOT NULL,
    [date]                 DATE         NOT NULL,
    sleep_duration_hours   DECIMAL(4,1) NOT NULL,
    work_duration_hours    DECIMAL(4,1) NOT NULL,
    physical_activity_min  SMALLINT     NOT NULL,
    screen_time_hours      DECIMAL(4,1) NOT NULL,
    planned_tasks          SMALLINT     NOT NULL,
    completed_tasks        SMALLINT     NOT NULL,
    task_completion_rate   DECIMAL(5,2) NOT NULL,
    productivity_score     TINYINT      NOT NULL
)
WITH (DISTRIBUTION = HASH(employee_id), CLUSTERED COLUMNSTORE INDEX);
ALTER TABLE dw.FACT_DAILY_ACTIVITY ADD CONSTRAINT PK_FACT_DAILY_ACTIVITY
    PRIMARY KEY NONCLUSTERED (employee_id, [date]) NOT ENFORCED;







